"use client";

import React from "react";
import { svgProps } from "@/types";

export const Svg: React.FC<svgProps> = ({
  svg,
  className,
  color = "#000000",
  width = "2",
  isClicked,
  isHovered,
}) => {
  color = isHovered ? "#ffffff" : isClicked ? "#ffffff" : color;

  return (
    <span className={isClicked ? className : " "}>{svg(color, width)}</span>
  );
};

